import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  collides,
  step,
  makeBricks,
  createState,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
  UP,
  DOWN,
  LEFT,
  RIGHT,
  BRICK_H,
  BRICK_W,
} from './neon.js';

// Helper to create a brick and ball setup
function setupCollision(ballPos, ballVel, brickPos) {
  const state = createState(1);
  state.ball = { ...state.ball, ...ballPos, ...ballVel };
  state.bricks = [{
    x: brickPos[0],
    y: brickPos[1],
    w: BRICK_W,
    h: BRICK_H,
    alive: true,
    points: 10,
  }];
  return state;
}

test('collides: clear overlap detected', () => {
  const ball = { x: 100, y: 100, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('collides: ball clearly away => no collision', () => {
  const ball = { x: 300, y: 300, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), false);
});

test('collides: edge contact (radius) detected', () => {
  const ball = { x: 85, y: 100, r: 8 }; // right edge of the ball at 93 > 90
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('step: bounce off the left wall', () => {
  const state = createState(1);
  state.ball = { x: 2, y: 200, r: 7, vx: -300, vy: 0 };
  step(state, 1 / 60);
  assert.ok(state.ball.vx > 0, 'horizontal velocity should flip to the right');
});

test('step: ball exiting through the bottom => lost', () => {
  const state = createState(1);
  state.ball = { x: 320, y: 500, r: 7, vx: 0, vy: 400 };
  const lost = step(state, 1 / 60);
  assert.equal(lost, true);
});

test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

// --- Issue #1: Brick Bounce Tests ---

// We need a way to test brick collisions. 
// Since brick collision is currently in frame(), 
// we should probably extract it to a testable function first.
// But for now, I'll use a helper that mimics frame's logic if I can't change the code.
// Actually, the prompt says "Ne modifie que game/neon.js et game/neon.test.js".
// I will modify neon.js to export a function that handles brick collisions.

// Note: Since I haven't modified neon.js yet, these tests will likely fail 
// or I can't call the function. I'll write them and then implement the fix.

