import {
  collides,
  step,
  makeBricks,
  createState,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
  UP,
  DOWN,
  LEFT,
  RIGHT,
  BRICK_H,
  BRICK_W,
  resolveBrickCollision,
} from './neon.js';

// Helper to create a brick and ball setup
function setupCollision(ballPos, ballVel, brickPos) {
  const state = createState(1);
  state.ball = { ...state.ball, ...ballPos, ...ballVel };
  state.bricks = [{
    x: brickPos[0],
    y: brickPos[1],
    w: BRICK_W,
    h: BRICK_H,
    alive: true,
    points: 10,
  }];
  return state;
}

test('collides: clear overlap detected', () => {
  const ball = { x: 100, y: 100, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('collides: ball clearly away => no collision', () => {
  const ball = { x: 300, y: 300, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), false);
});

test('collides: edge contact (radius) detected', () => {
  const ball = { x: 85, y: 100, r: 8 }; // right edge of the ball at 93 > 90
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('step: bounce off the left wall', () => {
  const state = createState(1);
  state.ball = { x: 2, y: 200, r: 7, vx: -300, vy: 0 };
  step(state, 1 / 60);
  assert.ok(state.ball.vx > 0, 'horizontal velocity should flip to the right');
});

test('step: ball exiting through the bottom => lost', () => {
  const state = createState(1);
  state.ball = { x: 320, y: 500, r: 7, vx: 0, vy: 400 };
  const lost = step(state, 1 / 60);
  assert.equal(lost, true);
});

test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

// --- Issue #1: Brick Bounce Tests ---

test('resolveBrickCollision: bounce from bottom (hit top face)', () => {
  const ball = { x: 100, y: 80, r: 7, vx: 0, vy: -100 };
  const brick = { x: 80, y: 80, w: 40, h: 20 };
  // Ball is moving UP, hits the bottom of the brick.
  // Ball center at 80, radius 7 -> bottom of ball at 87, top of brick at 80.
  // Overlap is on Y axis.
  resolveBrickCollision(ball, brick);
  assert.equal(Math.sign(ball.vy), DOWN, 'velocity should flip to DOWN');
  assert.ok(ball.y > 80 + 20, 'ball should be pushed out to the bottom');
});

test('resolveBrickCollision: bounce from top (hit bottom face)', () => {
  const ball = { x: 100, y: 60, r: 7, vx: 0, vy: 100 };
  const brick = { x: 80, y: 80, w: 40, h: 20 };
  // Ball is moving DOWN, hits the top of the brick.
  resolveBrickCollision(ball, brick);
  assert.equal(Math.sign(ball.vy), UP, 'velocity should flip to UP');
  assert.ok(ball.y < 80, 'ball should be pushed out to the top');
});

test('resolveBrickCollision: bounce from left (hit right face)', () => {
  const ball = { x: 130, y: 90, r: 7, vx: -100, vy: 0 };
  const brick = { x: 80, y: 80, w: 40, h: 20 };
  // Ball moving LEFT, hits the right side of the brick.
  resolveBrickCollision(ball, brick);
  assert.equal(Math.sign(ball.vx), RIGHT, 'velocity should flip to RIGHT');
  assert.ok(ball.x > 120, 'ball should be pushed out to the right');
});

test('resolveBrickCollision: bounce from right (hit left face)', () => {
  const ball = { x: 70, y: 90, r: 7, vx: 100, vy: 0 };
  const brick = { x: 80, y: 80, w: 40, h: 20 };
  // Ball moving RIGHT, hits the left side of the brick.
  resolveBrickCollision(ball, brick);
  assert.equal(Math.sign(ball.vx), LEFT, 'velocity should flip to LEFT');
  assert.ok(ball.x < 80, 'ball should be pushed out to the left');
});

test('resolveBrickCollision: corner hit flips both', () => {
  const ball = { x: 75, y: 75, r: 7, vx: 100, vy: -100 };
  const brick = { x: 80, y: 80, w: 40, h: 20 };
  // Near the top-left corner.
  resolveBrickCollision(ball, brick);
  assert.ok(ball.vx < 0 && ball.vy > 0, 'both components should flip');
});

